pragma solidity 0.6.12;

import { Ownable } from "./Ownable.sol";

/**
 * @notice Pausable
 * @dev Similar to OpenZeppelin's Pausable.
 * Differences:
 * - Has the pauser role
 * - External pause/unpause functions callable by the pauser
 * - No constructor
 * - No GSN support
